                // post.is_checked_out(i) == pre.is_checked_out(i)  (for i != head)
                // post.in_active_range(i) == pre.in_active_range(i)  (for i != head)

                // From pre.valid_storage_all(), we know pre.valid_storage_at_idx(i)
                // Since the state at index i is unchanged, post.valid_storage_at_idx(i) should hold too

