#[inductive(consume_end)]
fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    // In the consume_end transition:
    // 1. We move from ConsumerState::Consuming(head) to ConsumerState::Idle(next_head)
    // 2. We update the shared head from head to next_head
    // 3. We deposit a permission for cell at index head, which must be uninit()

    // We need to prove that post.valid_storage_all() holds

    // Let i be an arbitrary index in range
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        // Case analysis on whether i equals head (the index being modified)
        if i == pre.consumer.get_Consuming_0() {
            // Index i is the one being modified in this transition
            // In the pre-state, this index was checked out (no permission stored)
            // In the post-state, we've deposited the permission

            // Show that the permission was deposited correctly
            assert(post.storage.dom().contains(i));

            // Show that the permission is for the correct cell
            assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

            // Show that the permission indicates the cell is now empty (uninit)
            // This follows from the requirement that perm.is_uninit()
            assert(post.storage.index(i).is_uninit());

            // Determine if this index should be in the active range in post-state
            // The active range is determined by post.head and post.tail
            let in_active = post.in_active_range(i);
            if in_active {
                // If it's in active range, we'd expect it to be full, but we just made it uninit
                // So we need to show it's actually not in the active range

                // In the consume_end transition, we remove an element from the front of the queue
                // So the active range shrinks - elements that were previously active may no longer be
                // Specifically, the element at the head position is no longer active

                // Let's show that i (which equals head) is not in the active range in post-state
                let head = pre.consumer.get_Consuming_0();  // i == head
                let next_head = post.head;  // post.head == next_head == inc_wrap(head, len)

                // By definition of in_active_range and inc_wrap:
                // - If head <= tail (non-wrapped case), then active range is [head, tail)
                //   After consuming, head becomes next_head, so active range becomes [next_head, tail)
                //   Since i==head and next_head > head, i is no longer in the active range
                // - If head > tail (wrapped case), then active range is [head, len) U [0, tail)
                //   After consuming, head becomes next_head:
                //   * If next_head > head (normal increment), active range becomes [next_head, len) U [0, tail)
                //     Since i==head and next_head > head, i is no longer in [head, len) part
                //     Also i!=tail (because queue wasn't empty), so i is not in [0, tail) part if i>0
                //     If i==0, then head==0, and next_head==1, so 0 is not in [1,len) U [0,tail) iff tail!=0
                //     But we need to be more careful...

                // Actually, let's use the fact that in the pre-state, i==head was in the active range
                // (since we were consuming from it), and in the post-state, the head advances,
                // so i==head is no longer in the active range.

                assert(!post.in_active_range(i));
                assert(post.storage.index(i).is_uninit());  // matches expectation for inactive cell
            }

            // Therefore, post.valid_storage_at_idx(i) holds for i == head
        } else {
            // Index i is not the one being modified
            // We need to show that post.valid_storage_at_idx(i) still holds

            // Since nothing changed at index i, we have:
            // post.storage.index(i) == pre.storage.index(i)  (for i != head)
            // post.is_checked_out(i) == pre.is_checked_out(i)  (for i != head)
            // post.in_active_range(i) == pre.in_active_range(i)  (for i != head)

            // From pre.valid_storage_all(), we know pre.valid_storage_at_idx(i)
            // Since the state at index i is unchanged, post.valid_storage_at_idx(i) should hold too

            // Need to check the details:
            // 1. post.is_checked_out(i) == pre.is_checked_out(i)
            //    This holds because only consumer state changed, from Consuming(head) to Idle(next_head)
            //    Since i != head, is_checked_out is unchanged.

            // 2. post.storage.dom().contains(i) == pre.storage.dom().contains(i)
            //    This holds because we only added a permission at index head, not at index i.

            // 3. post.storage.index(i).id() == post.backing_cells.index(i as int)
            //    This holds because both storage and backing_cells are unchanged.

            // 4. The init/uninit status matches in_active_range
            //    This holds because in_active_range is unchanged for i != head.

            assert(post.valid_storage_at_idx(i));
        }
    }
}

